CREATE TABLE IF NOT EXISTS `eb_teayu_post` (`id` BIGINT NOT NULL AUTO_INCREMENT, `stall_id` BIGINT DEFAULT NULL, `author_id` INT NOT NULL, `content` VARCHAR(2000) NOT NULL, `image_urls` TEXT, `audit_status` TINYINT NOT NULL DEFAULT 0 COMMENT '0 pending 1 published 2 rejected 3 hidden', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `is_deleted` TINYINT(1) NOT NULL DEFAULT 0, PRIMARY KEY (`id`), KEY `idx_teayu_post_public` (`audit_status`,`is_deleted`,`stall_id`,`create_time`), KEY `idx_teayu_post_author` (`author_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `eb_teayu_comment` (`id` BIGINT NOT NULL AUTO_INCREMENT, `post_id` BIGINT NOT NULL, `author_id` INT NOT NULL, `parent_id` BIGINT DEFAULT NULL, `content` VARCHAR(1000) NOT NULL, `audit_status` TINYINT NOT NULL DEFAULT 0 COMMENT '0 pending 1 published 2 rejected 3 hidden', `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `is_deleted` TINYINT(1) NOT NULL DEFAULT 0, PRIMARY KEY (`id`), KEY `idx_teayu_comment_public` (`post_id`,`audit_status`,`is_deleted`,`create_time`), KEY `idx_teayu_comment_author` (`author_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `eb_teayu_reaction` (`id` BIGINT NOT NULL AUTO_INCREMENT, `post_id` BIGINT NOT NULL, `user_id` INT NOT NULL, `reaction_type` VARCHAR(16) NOT NULL, `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uk_teayu_reaction` (`post_id`,`user_id`,`reaction_type`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `eb_system_menu` (`pid`,`name`,`icon`,`perms`,`component`,`menu_type`,`sort`,`is_show`,`is_delte`,`create_time`,`update_time`)
SELECT 5,'茶余社区审核权限',NULL,'teayu:community:review','', 'A',0,0,0,NOW(),NOW()
WHERE NOT EXISTS (SELECT 1 FROM `eb_system_menu` WHERE `perms`='teayu:community:review' AND `is_delte`=0);
